import{z as l,x as o,o as A,c,q as n,j as r,D as a,d as e,s as i,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"策略容量案例","description":"","frontmatter":{"title":"策略容量案例","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-capacity-cases.md","filePath":"quant/cn-capacity-cases.md","lastUpdated":1791063341000}'),p={name:"quant/cn-capacity-cases.md"};function d(u,E,C,D,h,f){const B=o("Mermaid");return A(),c("div",null,[E[2]||(E[2]=n('<h1 id="策略容量案例" tabindex="-1">策略容量案例 <a class="header-anchor" href="#策略容量案例" aria-label="Permalink to &quot;策略容量案例&quot;">​</a></h1><div class="epigraph"><p>容量的上限往往不在市场深度，而在负反馈藏在哪：藏在监管里的策略监控合规余量，藏在价格里的监控贴水，藏在信号里的监控衰减斜率。</p><footer>—— 据本课程各课约束链与容量测算通则整理</footer></div><p><a href="/quant/cn-custody-counter">上一课</a>把链路搭通，上线前最后一问是规模：这套策略在中国市场能装多少钱。<a href="/quant/strategy-capacity">策略容量与拥挤</a>写了容量与拥挤的一般理论，<a href="/quant/capacity-participation">容量与参与率</a>与<a href="/quant/live-capacity-estimate">实盘容量估计</a>写了测量方法。本课写中国情境：容量由工具约束与监管阈值决定的部分，往往大于市场深度决定的部分。用三条约束链把问题走成案例，比抽象公式有用。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通用容量公式的分母是成交量与参与率，中国实践还要乘三个本地约束：监管阈值——撤单率与申报速率的监控线（<a href="/quant/cn-programmatic-filing">程序化交易的报备实践</a>与<a href="/quant/cn-fee-cancel-ratio">差异化收费与撤单率监控</a>）；工具上限——股指期货限仓与券源规模；产品形态——申赎与集中度（<a href="/quant/cn-fund-constraints">私募与公募的约束差异</a>）。缺任何一项，测算都会给出「理论上装得下、实际上装不下」的答案。</p><p><span class="marginnote">术语翻译：「负反馈」就是规模越大、阻力越强的机制——好比音响离麦克风太近会啸叫，系统会自动压低音量。容量问题的本质是找到你的策略放大之后「自己给自己踩刹车」的位置：刹车可能在监管（触线）、在价格（推深贴水）、或在信号（稀释超额），找错位置容量就会算错一个量级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>案例一，日内 T0：约束链是底仓规模 × 撤单率监控 × 参与率。信号再好，日内可交易的量由「不触监控线的申报节奏」决定；扩规模的边际从市场深度移到合规余量，底仓可用券与券息成本（<a href="/quant/cn-margin-lending-structure">融券与转融通</a>）再截一道。案例二，市场中性：约束链是空头工具容量 × 贴水拥挤反馈。规模越大，空头腿越把贴水买深（<a href="/quant/cn-stockindex-basis">股指期货与贴水</a>的负反馈），对冲成本回头吃超额；容量由「贴水加深多少仍能覆盖成本」反推，而不是由期货持仓限额单独决定。案例三，指数增强：约束链是跟踪误差 × 集中度 × 超额衰减，规模扩到一定程度，小市值高波动的超额源被迫收窄（<a href="/quant/index-enhancement-decay">指增产品超额衰减</a>），容量曲线在超额对规模的边际过零处见顶。</p>',8)),(A(),r(s,null,{default:a(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAP%5B%22%E7%AD%96%E7%95%A5%E5%AE%B9%E9%87%8F%22%5D%20--%3E%20T0%5B%22T0%EF%BC%9A%E5%BA%95%E4%BB%93%C3%97%E6%92%A4%E5%8D%95%E7%8E%87%C3%97%E5%8F%82%E4%B8%8E%E7%8E%87%22%5D%0A%20%20CAP%20--%3E%20NEU%5B%22%E4%B8%AD%E6%80%A7%EF%BC%9A%E7%A9%BA%E5%A4%B4%E5%B7%A5%E5%85%B7%C3%97%E8%B4%B4%E6%B0%B4%E5%8F%8D%E9%A6%88%22%5D%0A%20%20CAP%20--%3E%20ENH%5B%22%E6%8C%87%E5%A2%9E%EF%BC%9A%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%C3%97%E8%B6%85%E9%A2%9D%E8%A1%B0%E5%87%8F%22%5D%0A%20%20T0%20--%3E%20FB1%5B%22%E6%89%A9%E8%A7%84%E6%A8%A1%E5%85%88%E8%A7%A6%E5%90%88%E8%A7%84%E4%BD%99%E9%87%8F%22%5D%0A%20%20NEU%20--%3E%20FB2%5B%22%E6%89%A9%E8%A7%84%E6%A8%A1%E6%8E%A8%E6%B7%B1%E8%B4%B4%E6%B0%B4%EF%BC%8C%E6%88%90%E6%9C%AC%E5%90%83%E8%B6%85%E9%A2%9D%22%5D%0A%20%20ENH%20--%3E%20FB3%5B%22%E6%89%A9%E8%A7%84%E6%A8%A1%E7%A8%80%E9%87%8A%E8%B6%85%E9%A2%9D%E6%BA%90%22%5D%0A%20%20FB1%20--%3E%20CURVE%5B%22%E8%B6%85%E9%A2%9D-%E8%A7%84%E6%A8%A1%E6%9D%83%E8%A1%A1%E8%A1%A8%E8%BF%9B%E4%BA%A7%E5%93%81%E5%86%8C%22%5D%0A%20%20FB2%20--%3E%20CURVE%0A%20%20FB3%20--%3E%20CURVE%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"三条链的共同点是负反馈位置不同。T0 的负反馈在监管：扩规模先触线，利润上限由合规余量给出；中性的负反馈在价格：扩规模推深贴水、抬高自己的对冲成本；指增的负反馈在信号：规模稀释超额源。识别位置就知道监控什么——T0 监控撤单率余量，中性监控净贴水与对冲成本占超额比（第一课的读数工程在此变现），指增监控分域超额的衰减斜率。容量治理因此不是一次性测算，而是把这些指标写进产品册的持续监控。",-1)),(A(),r(s,null,{default:a(()=>[i(B,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20G1%5B%22%E4%B8%AD%E6%80%A7%E4%BA%A7%E5%93%81%E8%A7%84%E6%A8%A1%E6%89%A9%E5%A4%A7%22%5D%20--%3E%20S1%5B%22%E7%A9%BA%E5%A4%B4%E8%85%BF%E5%8A%A0%E4%BB%93%E8%82%A1%E6%8C%87%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20S1%20--%3E%20B1%5B%22%E8%B4%B4%E6%B0%B4%E8%A2%AB%E6%8E%A8%E6%B7%B1%22%5D%0A%20%20B1%20--%3E%20C1%5B%22%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A%20%20C1%20--%3E%20E1%5B%22%E5%87%80%E8%B6%85%E9%A2%9D%E8%A2%AB%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20E1%20--%3E%7C%22%E6%8A%95%E8%B5%84%E8%80%85%E8%B5%8E%E5%9B%9E%20%2F%20%E6%9A%82%E5%81%9C%E6%89%A9%E5%8B%9F%22%7C%20G1%0A%20%20MON%5B%22%E7%9B%91%E6%8E%A7%E6%8C%87%E6%A0%87%EF%BC%9A%E5%87%80%E8%B4%B4%E6%B0%B4%E4%B8%8E%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%E5%8D%A0%E8%B6%85%E9%A2%9D%E6%AF%94%22%5D%20-.%E7%9B%AF%E4%BD%8F.-%20B1%0A%20%20CAPX%5B%22%E5%87%80%E8%B6%85%E9%A2%9D%E6%8E%A5%E8%BF%91%E9%9B%B6%E7%9A%84%E8%A7%84%E6%A8%A1%20%3D%20%E5%AE%B9%E9%87%8F%E4%B8%8A%E9%99%90%22%5D%20-.%E5%8F%8D%E6%8E%A8.-%20E1%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">数字实例：某中性产品多头端年超额 8%，空头端贴水成本 5%，净超额 3%。规模翻倍后把年化贴水推深到 6.5%，净超额只剩 1.5%——超额被腰斩不是因为信号变差，而是规模自己把对冲成本抬上去了。容量上限就是「贴水加深到净超额归零」对应的规模。</span></p><p><span class="marginnote">容量应写成曲线：横轴规模、纵轴预期超额，每个规模档注明瓶颈是合规余量、贴水还是衰减；只写一个「最大规模」数字的产品册，通常意味着没做过负反馈分析。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课用概括口径讲约束链，不给具名产品与具体规模数字；监管阈值与市场深度随时间移动，测算要用当期参数重跑；容量在组织内的分配与治理超出本课范围。</p><p><span class="marginnote">常见误区：初学者容易以为容量等于「日均成交量 × 目标参与率」算出的一个数字。实际上中国市场的容量常常先卡在监管阈值（撤单率、申报速率）与工具上限（股指期货限仓、券源）上——市场深度还没碰到，合规余量已经用完。两个约束取更小的那个，才是真实容量。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>中国容量约束链三分支：监管阈值、工具与贴水、集中度与衰减。</li><li>负反馈位置决定监控指标：合规余量、净贴水、衰减斜率各管一条链。</li><li>容量是曲线不是点：产品册写超额-规模权衡与各档瓶颈。</li><li>出处：本课程各课约束链整理；容量一般理论见<a href="/quant/strategy-capacity">策略容量与拥挤</a>。</li></ul>',7))])}const q=l(p,[["render",d]]);export{F as __pageData,q as default};
